import{_ as t,c as n,a1 as o,o as a}from"./chunks/framework.nlCHK0Xf.js";const i="/15.jpg",r="/25.png",p=JSON.parse('{"title":"Use Debug Cable","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"starter/5 Use Debug Cable.md","filePath":"starter/5 Use Debug Cable.md"}'),s={name:"starter/5 Use Debug Cable.md"};function l(u,e,g,c,d,b){return a(),n("div",null,e[0]||(e[0]=[o('<h1 id="use-debug-cable" tabindex="-1">Use Debug Cable <a class="header-anchor" href="#use-debug-cable" aria-label="Permalink to &quot;Use Debug Cable&quot;">​</a></h1><p>The debug cable is highly useful for connecting the Puffin board to a PC, allowing users to modify settings and generate logs for debugging when the Puffin board malfunctions.</p><p><strong>Compatibility</strong> Please note that the debug cable is only compatible with Windows PCs using an x86 CPU. Mac users with ARM processors cannot use it, even with Parallels installed. However, Mac users with Intel CPUs can use it with Parallels.</p><h3 id="_1-connecting-the-debug-cable" tabindex="-1">1.Connecting the Debug Cable <a class="header-anchor" href="#_1-connecting-the-debug-cable" aria-label="Permalink to &quot;1.Connecting the Debug Cable&quot;">​</a></h3><p>Ensure that your Puffin board is powered off before connecting the debug cable. Locate the RX0 (pin 22) and TX0 (pin 24) pins on your Puffin board. These pins form the serial port pair used for debugging with a PC. Connect the debug cable&#39;s TX wire to the RX0 (pin 22) on the Puffin board, and the debug cable&#39;s RX wire to the TX0 (pin 24). It is crucial to avoid mixing up these connections, as doing so could potentially damage the board.</p><table tabindex="0"><thead><tr><th>Debug Cable</th><th style="text-align:center;">Puffin Board</th></tr></thead><tbody><tr><td>TX</td><td style="text-align:center;">RX0 (pin 22)</td></tr><tr><td>RX</td><td style="text-align:center;">TX0 (pin 24)</td></tr></tbody></table><p><img src="'+i+'" alt="Puffin connector"> Securely attach the debug cable to your PC&#39;s USB port. Power on your Puffin board. We’ve provided a debug cable in the bundle package. Please see the pinout of the debug cable in the following image. If puffin board is already powered on with an external power supply, there’s NO need to connect the 5V pin from the debug cable. <img src="'+r+'" alt="Puffin connector"> Power on your Puffin board.</p><h3 id="_2-configuring-serial-communication" tabindex="-1">2.Configuring Serial Communication <a class="header-anchor" href="#_2-configuring-serial-communication" aria-label="Permalink to &quot;2.Configuring Serial Communication&quot;">​</a></h3><p>Open a serial terminal application on your PC, (Test Serial Port)&#39;s serial monitor.</p><p><strong>Configure the serial communication settings as follows:</strong></p><ul><li><strong>Baud rate</strong>: 115200</li><li><strong>Data bits</strong>: 8</li><li><strong>Parity</strong>: None</li><li><strong>Stop bits</strong>: 1</li><li><strong>Flow control</strong>: None</li><li></li></ul><p>Select the appropriate COM port that corresponds to the debug cable. This is typically the port that appears after plugging in the debug cable.</p><h3 id="_3-using-the-debug-cable" tabindex="-1">3.Using the Debug Cable <a class="header-anchor" href="#_3-using-the-debug-cable" aria-label="Permalink to &quot;3.Using the Debug Cable&quot;">​</a></h3><p>With the debug cable connected and serial communication configured, you can now use it for various debugging purposes:</p><ul><li><strong>Viewing Log Messages</strong>The debug cable allows you to view log messages generated by the Puffin in real-time.</li><li><strong>Modifying Settings</strong> You can send commands through the serial terminal to modify various settings on the Puffin board. Refer to the documentation for a list of supported commands and their usage.</li><li><strong>Troubleshooting</strong> When the Puffin board encounters problems, the debug cable enables you to access detailed information and perform troubleshooting steps. You can view error messages, monitor system behavior, and make necessary adjustments. Remember to disconnect the debug cable when not in use to avoid any potential interference with the Puffin board&#39;s normal operation.</li></ul>',15)]))}const f=t(s,[["render",l]]);export{p as __pageData,f as default};
